/* ============================================================================
 * dossier_nav.js — PERMANENT SHARED RESEARCH LIBRARY NAVIGATOR
 * ----------------------------------------------------------------------------
 * Single source of truth for all per-dossier navigation in googledrive/blogs/.
 * Data:   dossiers.json  (regenerated by `python3 scripts/build_dossier_portal.py`)
 * Mount:  each *_dossier.html contains exactly:
 *            <div id="dossierNavSlot"></div>
 *            <script src="dossier_nav.js" defer></script>
 * Do NOT embed inline nav markup / nav CSS / dossier lists in individual
 * dossiers. To change nav appearance or grouping, edit THIS file only.
 * ==========================================================================*/
(function () {
  'use strict';

  var slot = document.getElementById('dossierNavSlot');
  if (!slot) return;

  var CSS = `
.dossier-nav-header{position:sticky;top:0;z-index:9999;width:100%;background:#f9fafb;border-bottom:2px solid #1f2937;font-family:'Inter',sans-serif;display:flex;align-items:center;justify-content:space-between;padding:0.5rem 1.25rem;gap:1rem;box-sizing:border-box}
.dossier-nav-inner{display:flex;align-items:center;justify-content:space-between;width:100%;gap:1rem}
.dossier-nav-left,.dossier-nav-right{display:flex;align-items:center;gap:0.5rem;min-width:0}
.nav-home-link{color:#1f2937;font-weight:600;font-size:0.95rem;text-decoration:none;white-space:nowrap}
.nav-home-link:hover{color:#1d4ed8}
.nav-sep{color:#d1d5db;font-weight:700;user-select:none}
.nav-market-flag{font-size:1rem}
.nav-badge{display:inline-flex;align-items:center;gap:0.3rem;padding:0.2rem 0.5rem;border-radius:0.25rem;font-size:0.75rem;font-weight:600;white-space:nowrap}
.nav-badge-core-alpha{background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe}
.nav-badge-tactical-momentum{background:#f5f3ff;color:#6d28d9;border:1px solid #ddd6fe}
.nav-badge-leveraged-satellite{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}
.nav-badge-buy{background:#ecfdf5;color:#047857;border:1px solid #a7f3d0}
.nav-badge-accumulate{background:#ecfdf5;color:#047857;border:1px solid #a7f3d0}
.nav-badge-compounding{background:#eef2ff;color:#4338ca;border:1px solid #c7d2fe}
.nav-badge-wait{background:#fffbeb;color:#b45309;border:1px solid #fde68a}
.nav-badge-trim{background:#fff7ed;color:#c2410c;border:1px solid #fed7aa}
.nav-badge-reject{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}
.nav-current-title{display:flex;align-items:baseline;gap:0.5rem;min-width:0}
.nav-sym{font-family:'JetBrains Mono',monospace;font-weight:700;font-size:1.05rem;color:#1f2937;white-space:nowrap}
.nav-company-name{font-size:0.9rem;color:#4b5563;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:280px}
.nav-pager-btn{font-family:'JetBrains Mono',monospace;font-size:0.85rem;font-weight:600;color:#1f2937;background:#fff;border:1px solid #d1d5db;padding:0.35rem 0.6rem;border-radius:0.375rem;text-decoration:none;white-space:nowrap}
.nav-pager-btn:hover{border-color:#1d4ed8;color:#1d4ed8}
.nav-quick-jump{font-family:'Inter',sans-serif;font-size:0.85rem;color:#1f2937;background:#fff;border:1px solid #d1d5db;padding:0.3rem 0.4rem;border-radius:0.375rem;max-width:260px}
.nav-index-btn{font-family:'Inter',sans-serif;font-size:0.8rem;font-weight:600;color:#1d4ed8;background:#eff6ff;border:1px solid #bfdbfe;padding:0.35rem 0.6rem;border-radius:0.375rem;text-decoration:none;white-space:nowrap}
.nav-index-btn:hover{background:#dbeafe}
@media (max-width:960px){.nav-company-name,.nav-sep{display:none}}
@media (max-width:720px){.dossier-nav-right .nav-quick-jump{max-width:150px}}`;

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  /* Dossiers now live in market subfolders (blogs/IN/, blogs/US/) while this
     script and dossiers.json stay at the blogs/ root. Resolve every shared
     destination against this script's own URL so navigation works from any
     page depth, on Pages, localhost, or file://. */
  var NAVBASE = (function () {
    try {
      var src = document.currentScript && document.currentScript.src;
      if (src) return new URL('.', src).href;
    } catch (e) {}
    return '';
  })();
  function navUrl(rel) {
    try { return new URL(rel, NAVBASE || document.baseURI).href; }
    catch (e) { return rel; }
  }
  function sameFile(entry, here) {
    return entry === here || entry.slice(-here.length - 1) === '/' + here;
  }

  function stratClass(s) {
    s = (s || '').toLowerCase();
    if (s.indexOf('core') >= 0) return 'nav-badge-core-alpha';
    if (s.indexOf('leveraged') >= 0) return 'nav-badge-leveraged-satellite';
    return 'nav-badge-tactical-momentum';
  }

  function verdictClass(v) {
    v = (v || '').toUpperCase();
    if (v.indexOf('BUY') >= 0) return 'nav-badge-buy';
    if (v.indexOf('ACCUMULATE') >= 0) return 'nav-badge-accumulate';
    if (v.indexOf('COMPOUND') >= 0) return 'nav-badge-compounding';
    if (v.indexOf('TRIM') >= 0) return 'nav-badge-trim';
    if (v.indexOf('REJECT') >= 0 || v.indexOf('AVOID') >= 0) return 'nav-badge-reject';
    return 'nav-badge-wait';
  }

  /* Mutually-exclusive bucketing, highest priority first. Each dossier
     appears in exactly one group (prevents double-selection drift). */
  function bucketOf(d) {
    if (d.is_archived) return '\uD83D\uDEA1 Archived / Rejected';
    if (d.is_holding) return '\uD83D\uDCEC Portfolio Holdings';
    var v = d.norm_verdict || '';
    if (/BUY|ACCUMULATE|COMPOUND/.test(v)) return '\uD83D\uDE80 High Priority Buys';
    if ((d.strat_clean || '').toLowerCase().indexOf('tactical') >= 0) return '\u2694\uFE0F Tactical Momentum';
    if (/WAIT|WATCH/.test(v)) return '\u23F3 Quality on Watch';
    if (d.market === 'US') return '\uD83C\uDDFA\uD83C\uDDF8 US Equities & Tech';
    return '\uD83C\uDDEE\uD83C\uDCF1 Indian Quality Leaders';
  }

  function render(list) {
    var here = location.pathname.split('/').pop();
    var i = -1;
    for (var k = 0; k < list.length; k++) if (sameFile(list[k].file, here)) { i = k; break; }
    var d = i >= 0 ? list[i] : null;

    var style = document.createElement('style');
    style.id = 'dossier-nav-styles';
    style.textContent = CSS;
    slot.parentNode.insertBefore(style, slot);

    var nav = document.createElement('nav');
    nav.className = 'dossier-nav-header';
    nav.id = 'dossierNav';
    nav.setAttribute('aria-label', 'Research Library Navigation');
    slot.parentNode.insertBefore(nav, slot);

    var inner = document.createElement('div');
    inner.className = 'dossier-nav-inner';

    var left = document.createElement('div');
    left.className = 'dossier-nav-left';
    left.innerHTML =
      '<a class="nav-home-link" href="' + navUrl('index.html') + '">\u2302 Research Library</a>' +
      '<span class="nav-sep">|</span>' +
      '<span class="nav-market-flag">' + (d ? (d.market === 'US' ? '\uD83C\uDDFA\uD83C\uDDF8' : '\uD83C\uDDEE\uD83C\uDCF1') : '\uD83D\uDCDA') + '</span>' +
      (d ? '<span class="nav-badge ' + stratClass(d.strat_clean) + '">' + esc(d.strat_badge) + '</span>' : '') +
      (d ? '<span class="nav-badge ' + verdictClass(d.norm_verdict) + '">' + esc(d.verdict_icon) + ' ' + esc(d.norm_verdict) + '</span>' : '') +
      '<span class="nav-current-title"><span class="nav-sym">' + esc(d ? d.symbol : here) + '</span>' +
      (d ? '<span class="nav-company-name">' + esc(d.company_name) + '</span>' : '') + '</span>';

    var right = document.createElement('div');
    right.className = 'dossier-nav-right';

    function pager(href, label) {
      var a = document.createElement('a');
      a.className = 'nav-pager-btn';
      a.href = href;
      a.textContent = label;
      return a;
    }

    var prev = null, next = null;
    if (d && list.length > 1) {
      prev = list[(i - 1 + list.length) % list.length];
      next = list[(i + 1) % list.length];
      right.appendChild(pager(navUrl(prev.file), '\u2190 ' + prev.symbol));
    }

    var sel = document.createElement('select');
    sel.className = 'nav-quick-jump';
    sel.setAttribute('aria-label', 'Jump to dossier');
    var groups = {};
    list.forEach(function (x) {
      var g = bucketOf(x);
      (groups[g] = groups[g] || []).push(x);
    });
    Object.keys(groups).forEach(function (g) {
      var og = document.createElement('optgroup');
      og.label = g;
      groups[g].forEach(function (x) {
        var o = document.createElement('option');
        o.value = navUrl(x.file);
        o.textContent = (x.market === 'US' ? '\uD83C\uDDFA\uD83C\uDDF8 ' : '\uD83C\uDDEE\uD83C\uDCF1 ') + x.symbol + ' \u2014 ' + x.company_name;
        if (sameFile(x.file, here)) o.selected = true;
        og.appendChild(o);
      });
      sel.appendChild(og);
    });
    sel.addEventListener('change', function () {
      if (sel.value) location.href = sel.value;
    });
    right.appendChild(sel);

    if (d && list.length > 1) right.appendChild(pager(navUrl(next.file), next.symbol + ' \u2192'));

    var idx = document.createElement('a');
    idx.className = 'nav-index-btn';
    idx.href = navUrl('index.html');
    idx.textContent = '\uD83D\uDCDA Index (' + list.length + ' Dossiers)';
    right.appendChild(idx);

    inner.appendChild(left);
    inner.appendChild(right);
    nav.appendChild(inner);
  }

  fetch(navUrl('dossiers.json'))
    .then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    })
    .then(function (list) {
      if (!Array.isArray(list) || !list.length) throw new Error('empty registry');
      render(list);
    })
    .catch(function () {
      slot.innerHTML = '<nav class="dossier-nav-header" style="background:#fffbeb;border-bottom:2px solid #b45309;padding:0.5rem 1.25rem;font-family:Inter,sans-serif;font-size:0.85rem;color:#92400e">⚠ Shared navigation unavailable — open via <a href="' + navUrl('index.html') + '">index.html</a> (file:// blocks the registry fetch)</nav>';
    });
})();
